begin;
select plan(11);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values
('a7777777-7777-4777-8777-777777777777','00000000-0000-0000-0000-000000000000','authenticated','authenticated','phasec-bundle-buyer@example.invalid','',now(),now(),now()),
('a8888888-8888-4888-8888-888888888888','00000000-0000-0000-0000-000000000000','authenticated','authenticated','phasec-bundle-creator@example.invalid','',now(),now(),now()) on conflict(id) do nothing;
insert into public.marketplace_creators(id,user_id,display_name,slug,status) values('c7777777-7777-4777-8777-777777777777','a8888888-8888-4888-8888-888888888888','Bundle Creator','phasec-bundle-creator','verified') on conflict(id) do update set status='verified';
insert into public.marketplace_categories(id,slug,name) values('d7777777-7777-4777-8777-777777777777','phasec-bundle-cat','Bundle category') on conflict(id) do nothing;
insert into public.marketplace_products(id,creator_id,category_id,slug,name,summary,product_type,pricing_type,price_minor,currency,status,created_by) values('e7777777-7777-4777-8777-777777777777','c7777777-7777-4777-8777-777777777777','d7777777-7777-4777-8777-777777777777','phasec-bundle-item','Bundle item','Fixture','workflow','one_time',10000,'USD','published','a8888888-8888-4888-8888-888888888888') on conflict(id) do nothing;
insert into public.marketplace_product_versions(id,product_id,version,artifact_path,artifact_sha256,verification_status,created_by) values('f7777777-7777-4777-8777-777777777777','e7777777-7777-4777-8777-777777777777','1.0.0','private/phasec-bundle.zip',repeat('a',64),'approved','a8888888-8888-4888-8888-888888888888') on conflict(id) do nothing;
update public.marketplace_products set current_version_id='f7777777-7777-4777-8777-777777777777' where id='e7777777-7777-4777-8777-777777777777';
insert into public.marketplace_bundles(id,creator_id,slug,title,description,status,pricing_type,price_minor,currency) values('b7777777-7777-4777-8777-777777777777','c7777777-7777-4777-8777-777777777777','phasec-paid-bundle','Paid bundle','Fixture','published','one_time',10000,'USD') on conflict(id) do nothing;
insert into public.marketplace_bundle_items(bundle_id,product_id,product_version_id,position) values('b7777777-7777-4777-8777-777777777777','e7777777-7777-4777-8777-777777777777','f7777777-7777-4777-8777-777777777777',0) on conflict do nothing;
insert into public.marketplace_bundle_versions(id,bundle_id,version,manifest,manifest_sha256,verification_status,verified_by,verified_at) values('b8888888-8888-4888-8888-888888888888','b7777777-7777-4777-8777-777777777777',1,'[{"product_id":"e7777777-7777-4777-8777-777777777777","product_version_id":"f7777777-7777-4777-8777-777777777777","position":0}]',encode(digest('[{"product_id":"e7777777-7777-4777-8777-777777777777","product_version_id":"f7777777-7777-4777-8777-777777777777","position":0}]','sha256'),'hex'),'approved','a8888888-8888-4888-8888-888888888888',now()) on conflict(id) do nothing;
update public.marketplace_bundles set current_version_id='b8888888-8888-4888-8888-888888888888' where id='b7777777-7777-4777-8777-777777777777';
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','a7777777-7777-4777-8777-777777777777',true);
select throws_ok($$select public.marketplace_create_bundle_purchase('a7777777-7777-4777-8777-777777777777','b7777777-7777-4777-8777-777777777777','stripe','bundle-key-0001')$$,'42501','permission denied for function marketplace_create_bundle_purchase','buyer cannot directly create provider bundle purchase');
reset role;set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
select set_config('test.bundle_purchase_id',(public.marketplace_create_bundle_purchase('a7777777-7777-4777-8777-777777777777','b7777777-7777-4777-8777-777777777777','stripe','bundle-key-0001')->>'purchase_id'),true);
select lives_ok($$select public.marketplace_finalize_bundle_payment('stripe','bundle-event-0001',current_setting('test.bundle_purchase_id')::uuid,'pi-bundle-0001',10000,'USD',repeat('b',64),now())$$,'bundle payment finalization atomically grants entitlements and splits ledger');
select is((select status from public.marketplace_bundle_purchases where id=current_setting('test.bundle_purchase_id')::uuid),'paid','bundle purchase paid state persisted');
select is((select count(*)::integer from public.marketplace_bundle_entitlements where purchase_id=current_setting('test.bundle_purchase_id')::uuid and status='active'),1,'buyer bundle entitlement is active');
select is((select sum(amount_minor)::bigint from public.marketplace_financial_ledger where bundle_purchase_id=current_setting('test.bundle_purchase_id')::uuid and entry_type='creator_earning'),8000::bigint,'creator receives 80 percent of gross bundle sale');
select is((public.marketplace_finalize_bundle_payment('stripe','bundle-event-0001',current_setting('test.bundle_purchase_id')::uuid,'pi-bundle-0001',10000,'USD',repeat('b',64),now())->>'status'),'duplicate_bundle_payment','duplicate provider bundle payment is idempotent');
select lives_ok($$select public.marketplace_reverse_bundle_payment('stripe','bundle-refund-0001',current_setting('test.bundle_purchase_id')::uuid,'refund',10000,repeat('c',64),now())$$,'bundle refund reverses ledger and revokes entitlements');
select is((select status from public.marketplace_bundle_entitlements where purchase_id=current_setting('test.bundle_purchase_id')::uuid),'revoked','refund revokes bundle entitlement');
select is((select status from public.marketplace_bundle_purchases where id=current_setting('test.bundle_purchase_id')::uuid),'refunded','bundle purchase refund state persisted');
select is((select sum(amount_minor)::bigint from public.marketplace_financial_ledger where bundle_purchase_id=current_setting('test.bundle_purchase_id')::uuid and entry_type in ('gross_sale','refund')),0::bigint,'full bundle refund nets gross ledger to zero');
select is((public.marketplace_reverse_bundle_payment('stripe','bundle-refund-0001',current_setting('test.bundle_purchase_id')::uuid,'refund',10000,repeat('c',64),now())->>'status'),'duplicate_event','duplicate bundle reversal is idempotent');
select * from finish();
rollback;
